<?php
namespace App\Services; use App\Enums\{AffiliateTier, WalletTransactionType}; use App\Models\{Order, Referral, User};
class ReferralService { public function registerReferral(User $referrer, User $referred): Referral { throw_if($referrer->is($referred), \InvalidArgumentException::class, 'Self referrals are not allowed.'); return Referral::firstOrCreate(['referrer_id'=>$referrer->id,'referred_user_id'=>$referred->id], ['status'=>'pending']); } public function rewardFor(Order $order): ?Referral { $referral = Referral::where('referred_user_id',$order->customer_id)->where('status','pending')->first(); if (!$referral || $order->total_price < 50000) return null; $tier = AffiliateTier::tryFrom($referral->referrer->affiliate_tier ?? 'bronze') ?? AffiliateTier::Bronze; $reward = round((float)$order->total_price * $tier->commissionRate(), 2); app(WalletService::class)->credit($referral->referrer, WalletTransactionType::ReferralReward, $reward, "Referral reward for order {$order->order_code}"); $referral->update(['order_id'=>$order->id,'reward_amount'=>$reward,'status'=>'approved']); return $referral->refresh(); } }
